// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool ok;
        try c.renounceRole(role, caller) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "renouncing a role for oneself must never revert");
    }
}
